{
  "devType": "feature",
  "goal": "Restore a single, explicit, and verifiable contract between routed flow parser options and displayed help while preserving existing command behavior and the separate flow query contract.",
  "analysis": {
    "problem": "The routed flow registry currently keeps parser input definitions and help presentation separate, allowing accepted options, leaf and group help, row spacing, and ordering to diverge. Issue 521's restart contract supersedes historical audit counts and unresolved revision 008, and requires the current registry to be re-enumerated.",
    "proposedApproach": "Use the existing flow command authority to make parser contracts, leaf help, group projections, and the three public group-help routes agree. Preserve the existing validators, target guards, runtime resolution, lifecycle behavior, and independent query ownership while making the retained public contracts and their verification boundaries explicit for Spec.",
    "validation": "Validate every shared routed leaf, including resume and prepare, through registry and parser contract coverage. Add focused real-dispatcher CLI checks for leaf, group, and no-leaf help, option intersections, ordering and spacing boundaries, guarded commands, runtime path forms, rejection and exit behavior, plus independent query regressions. Confirm that command execution semantics and out-of-scope limits remain unchanged."
  },
  "decisionMap": {
    "knownFacts": [
      "must treat Issue 521's 2026-09-24 Restart contract as authoritative; unresolved revision 008 is not an approved specification.",
      "must re-enumerate the current FLOW_COMMANDS registry; the restart baseline describes 66 leaves, 65 shared routed leaves, and query as the explicit custom-parser exception without making those counts hard-coded acceptance data.",
      "must preserve the existing CommandDefinition and FLOW_COMMANDS authority, typed distinctions among flag, required-value, optional-value, and implicit help options, and direct-child group option intersection semantics.",
      "must cover flow group help through flow group help, help flow group, and flow group without a leaf, with visible row separation and deterministic name-based ordering.",
      "must preserve existing selector parsing, validators, target guards, runtime directory precedence, rejection lifecycle, exit behavior, and query stdin/request-file/help/error behavior.",
      "must verify retained public behavior through real dispatcher or CLI paths and must separate exhaustive routed parser coverage from focused public entry-point coverage.",
      "must keep the project dependency-free and agent-independent; arbitrary validation limits and command-semantic changes are outside help consistency."
    ],
    "decisionPoints": [
      "must use deterministic canonical name ordering as the default for subcommands and options, with any explicit display-order metadata and its tie-breaking rules bounded in Spec.",
      "must make the structured accepted-option contract the authority for Usage and Options rows while retaining command-specific prose, examples, and localization.",
      "must treat query as an independent parser and help surface rather than extending the shared routed migration to it."
    ],
    "resolvedByProjectRules": [
      "must not create a parallel command registry, reverse-parse hand-written help as authority, or add a thin duplicate implementation when the existing command authority can be extended.",
      "must not ask the user to reconfirm requirements already stated by Issue 521 or choose an unresolved design alternative that the Issue and project rules already determine.",
      "must preserve alpha policy, including removal of obsolete compatibility paths, no external dependency additions, and no agent-host-specific lifecycle dependency.",
      "must keep internal context and injected runtime state out of the public option inventory and must reuse the existing owner for each boundary decision."
    ],
    "requiresUserJudgment": [],
    "deferredToSpec": [
      {
        "boundary": "must define the per-leaf input inventory for all shared routed commands",
        "relevance": "The inventory needs to record positional and rest arity, flag and option value status, cardinality, formats, domains, empty values, conditional combinations, path semantics, existing size policies, and the validator that owns each decision.",
        "owner": "spec"
      },
      {
        "boundary": "must map every retained public help and execution surface to its current or new owner",
        "relevance": "The mapping needs to cover leaf help, all three group-help routes, parser acceptance, execution, target guards, runtime paths, query regression, hooks, configuration, generated artifacts, side effects, and unchanged categories.",
        "owner": "spec"
      },
      {
        "boundary": "must define the observable rendering and option-projection acceptance boundaries",
        "relevance": "The boundaries need to cover canonical option rows, required versus optional values, group intersections, aliases, locale-independent order, at-least-two-space row separation, long-name limits, and synthetic renderer-only names without adding a production name limit.",
        "owner": "spec"
      },
      {
        "boundary": "must enumerate shared target guards and preserved runtime and rejection behavior",
        "relevance": "The Spec needs to identify applicable leaves and existing owners for matching, mismatch, invalid combinations, missing guards, agent-work-dir syntax, log precedence, durable cleanup, lifecycle hooks, diagnostics, and exit codes.",
        "owner": "spec"
      },
      {
        "boundary": "must assign each verification concern to one primary test layer",
        "relevance": "The assignment needs to retain an exhaustive routed parser matrix, focused public CLI behavior, real dispatcher assertions, isolated fixtures, and independent query coverage without duplicating the same invalid-input matrix.",
        "owner": "spec"
      }
    ]
  },
  "scopeVerification": {
    "in": [
      "must include the existing routed flow command collection, including resume, prepare, get, set, run, and report/show leaves.",
      "must include one shared option contract for parser acceptance, leaf help, direct-child group help, and implicit -h, --help presentation.",
      "must include the three public group-help entry points, deterministic ordering, visible spacing, long-name renderer boundaries, and the group option intersection contract.",
      "must include preservation of existing input validators, target guards, runtime directory and log-path rules, rejection lifecycle, diagnostics, exit codes, and command execution semantics.",
      "must include behavior-level verification for parser acceptance, help rendering, guarded commands, runtime paths, and query regression through their real public paths.",
      "must include the per-leaf inventory and owner mapping required for the next Spec without introducing a new blanket validator or speculative limit."
    ],
    "out": [
      "must exclude flow query from the shared routed parser, admission, help-projection, and exhaustive matrix migration while retaining its independent regression coverage.",
      "must exclude changes to command semantics, target-guard decisions, runtime directory behavior, or existing validation policy.",
      "must exclude arbitrary new resource limits, a new command registry, external dependencies, and agent-specific lifecycle mechanisms.",
      "must exclude historical audit counts or unresolved revision 008 as fresh authority, as well as recovery of the stopped historical flow."
    ]
  },
  "impactOnExisting": [
    "must preserve existing flow command invocation, validators, guard evaluation, hooks, runtime initialization, logging, failure diagnostics, and successful or failing exit behavior.",
    "must update the retained flow help surfaces so their accepted options, group intersections, row order, and spacing agree without removing command-specific prose, examples, or localization.",
    "must preserve the independent query parser and its stdin, request-file, help, and error behavior while keeping it outside shared routed projections and matrices.",
    "must extend contract and public CLI verification across existing registry, dispatcher, help, runtime, guard, and query touchpoints, with unchanged behavior explicitly recorded where no implementation change is required.",
    "must retain the no-external-dependency package boundary and agent-independent execution model."
  ],
  "questionLedger": {
    "revision": 0,
    "publication": "draft-worker-publication",
    "evidenceDigest": "6443375a5b99258635088695cdefa410f2f160a795b8c59322674b4b740532a3",
    "questions": []
  },
  "openQuestions": []
}
